-- Generated by Murakumo: load tpch_erp.orders (append), without Murakumo. Run it from the project folder.

-- The files under landing/tpch_erp/orders/ that were not loaded before.
create or replace temp table new_rows as
select cast(o_orderkey as BIGINT) as o_orderkey, cast(o_custkey as BIGINT) as o_custkey, cast(o_orderstatus as VARCHAR) as o_orderstatus, cast(o_totalprice as DECIMAL(15,2)) as o_totalprice, cast(o_orderdate as DATE) as o_orderdate, cast(o_orderpriority as VARCHAR) as o_orderpriority, cast(o_clerk as VARCHAR) as o_clerk, cast(o_shippriority as INTEGER) as o_shippriority, cast(o_comment as VARCHAR) as o_comment, filename
from read_json('landing/tpch_erp/orders/orders_*.jsonl', format = 'newline_delimited', filename = true, columns = {'o_orderkey': 'BIGINT', 'o_custkey': 'BIGINT', 'o_orderstatus': 'VARCHAR', 'o_totalprice': 'DECIMAL(15,2)', 'o_orderdate': 'DATE', 'o_orderpriority': 'VARCHAR', 'o_clerk': 'VARCHAR', 'o_shippriority': 'INTEGER', 'o_comment': 'VARCHAR'})
where parse_filename(filename) not in (select parse_filename(path) from audit.loaded_files where table_name = 'orders');
-- Append: the new files' rows are added.
insert into raw_tpch_erp.orders (o_orderkey, o_custkey, o_orderstatus, o_totalprice, o_orderdate, o_orderpriority, o_clerk, o_shippriority, o_comment, _ingested_at, _batch_id)
select o_orderkey, o_custkey, o_orderstatus, o_totalprice, o_orderdate, o_orderpriority, o_clerk, o_shippriority, o_comment, now(), parse_filename(filename) from new_rows;
-- Remember the files, so the next run skips them.
insert into audit.loaded_files (table_name, path, size, sha256, rows_ingested, batch_id, loaded_at)
select 'orders', filename, null, null, count(*), parse_filename(filename), now()
from new_rows group by filename;
drop table new_rows;
